import { status, type CallOptions, type requestCallback } from '@grpc/grpc-js'
import { GraphQLError } from 'graphql'
import type { ListFramesRequest } from '../generated/frameinventory/v1/ListFramesRequest'
import type { ListFramesResponse__Output } from '../generated/frameinventory/v1/ListFramesResponse'
import type { Resolvers } from '../generated/graphql'

export interface FrameClient {
  listFrames(
    request: ListFramesRequest,
    options: CallOptions,
    callback: requestCallback<ListFramesResponse__Output>,
  ): void
  close(): void
}

export function createFrameResolvers(client: FrameClient) {
  return {
    Query: {
      frames(_parent, args) {
        const request: ListFramesRequest = {
          page: args.page ?? undefined,
          size: args.size ?? undefined,
        }
        return new Promise<ListFramesResponse__Output>((resolve, reject) => {
          client.listFrames(
            request,
            { deadline: Date.now() + 5_000 },
            (error, response) => {
              if (error?.code === status.INVALID_ARGUMENT) {
                reject(
                  new GraphQLError(error.details, {
                    extensions: { code: 'BAD_USER_INPUT' },
                  }),
                )
              } else if (
                error?.code === status.UNAVAILABLE ||
                error?.code === status.DEADLINE_EXCEEDED
              ) {
                reject(
                  new GraphQLError('Frame service is unavailable', {
                    extensions: { code: 'SERVICE_UNAVAILABLE' },
                  }),
                )
              } else if (error || !response) {
                reject(
                  new GraphQLError('Could not list frames', {
                    extensions: { code: 'INTERNAL_SERVER_ERROR' },
                  }),
                )
              } else {
                resolve(response)
              }
            },
          )
        })
      },
    },
    Frame: {
      attributes(frame) {
        if (!frame.attributes) {
          throw new GraphQLError('Frame attributes are unavailable', {
            extensions: { code: 'INTERNAL_SERVER_ERROR' },
          })
        }
        return frame.attributes
      },
    },
  } satisfies Resolvers
}
import { expect, jest, test } from '@jest/globals'
import type { ListFramesResponse__Output } from '../src/generated/frameinventory/v1/ListFramesResponse'
import type { FrameClient } from '../src/resolvers/frames'
import { createServer } from '../src/server'

test('frames requests the specified gRPC page and returns frames with pagination metadata', async () => {
  const frame = {
    frameId: 'FRAME-001',
    versionId: '9007199254740993',
    attributes: { status: 'LIVE', address: '10 Test Street' },
  }
  const pagination = { page: 1, size: 1, hasNext: true }
  const page: ListFramesResponse__Output = {
    ...pagination,
    items: [
      {
        ...frame,
        attributes: {
          ...frame.attributes,
          location: null,
          format: null,
          premium: false,
        },
        validFrom: null,
        validTo: null,
        current: true,
        externalReferences: {},
        linkedFrameIds: [],
      },
    ],
  }
  const client = {
    listFrames: jest.fn<FrameClient['listFrames']>(
      (_request, _options, callback) => callback(null, page),
    ),
    close: jest.fn(),
  }
  const server = createServer(client)

  try {
    const response = await server.executeOperation({
      query: `
        query {
          frames(page: 1, size: 1) {
            items {
              frameId
              versionId
              attributes {
                status
                address
              }
            }
            page
            size
            hasNext
          }
        }
      `,
    })

    expect(client.listFrames).toHaveBeenCalledTimes(1)
    expect(client.listFrames).toHaveBeenCalledWith(
      { page: 1, size: 1 },
      { deadline: expect.any(Number) },
      expect.any(Function),
    )
    expect(response.body).toMatchObject({
      kind: 'single',
      singleResult: {
        data: { frames: { ...pagination, items: [frame] } },
        errors: undefined,
      },
    })
  } finally {
    await server.stop()
  }
})

